-- Migration 20261022000100: Update Perak/Malaysian guidance so clean plastic, glass, and metal are eligible
update public.pbt_rule_sets
set rules = '{"label":"Malaysian SAS Guidance (Perak)","classes":{
    "metal":{"material":"recyclable","conditionRules":{"clean_dry":{"eligibility":"eligible","reason":"Clean, dry metal cans and tins are eligible for recycling pickup under Malaysian SAS guidance."},"contaminated_wet":{"eligibility":"not_eligible","reason":"Only clean and dry items should be offered."},"broken_unsafe":{"eligibility":"restricted","reason":"Do not offer sharp or unsafe metal."},"unknown":{"eligibility":"needs_confirmation","reason":"Confirm the metal item is clean and dry."}}},
    "trash":{"material":"not_recyclable","conditionRules":{"clean_dry":{"eligibility":"not_eligible","reason":"General waste is not accepted for recycling pickup."},"contaminated_wet":{"eligibility":"not_eligible","reason":"General waste is not accepted for recycling pickup."},"broken_unsafe":{"eligibility":"not_eligible","reason":"General waste is not accepted for recycling pickup."},"unknown":{"eligibility":"not_eligible","reason":"General waste is not accepted for recycling pickup."}}},
    "glass":{"material":"recyclable","conditionRules":{"clean_dry":{"eligibility":"eligible","reason":"Clean, intact glass bottles and jars are eligible for recycling pickup under Malaysian SAS guidance."},"contaminated_wet":{"eligibility":"not_eligible","reason":"Only clean and dry items should be offered."},"broken_unsafe":{"eligibility":"restricted","reason":"Broken glass is unsafe; do not place it in community pickup."},"unknown":{"eligibility":"needs_confirmation","reason":"Confirm the glass is intact and clean."}}},
    "paper":{"material":"recyclable","conditionRules":{"clean_dry":{"eligibility":"eligible","reason":"Clean, dry paper is eligible for recycling pickup under Malaysian SAS guidance."},"contaminated_wet":{"eligibility":"not_eligible","reason":"Wet or contaminated paper is not eligible."},"broken_unsafe":{"eligibility":"not_eligible","reason":"Separate any unsafe contamination before pickup."},"unknown":{"eligibility":"needs_confirmation","reason":"Check that the paper is clean and dry."}}},
    "cardboard":{"material":"recyclable","conditionRules":{"clean_dry":{"eligibility":"eligible","reason":"Clean, dry cardboard is eligible for recycling pickup under Malaysian SAS guidance."},"contaminated_wet":{"eligibility":"not_eligible","reason":"Wet or contaminated cardboard is not eligible."},"broken_unsafe":{"eligibility":"not_eligible","reason":"Separate any unsafe contamination before pickup."},"unknown":{"eligibility":"needs_confirmation","reason":"Check that the cardboard is clean and dry."}}},
    "plastic":{"material":"recyclable","conditionRules":{"clean_dry":{"eligibility":"eligible","reason":"Clean, dry plastic bottles and containers are eligible for recycling pickup under Malaysian SAS guidance."},"contaminated_wet":{"eligibility":"not_eligible","reason":"Only clean and dry items should be offered."},"broken_unsafe":{"eligibility":"restricted","reason":"Do not offer sharp or unsafe plastic."},"unknown":{"eligibility":"needs_confirmation","reason":"Confirm the plastic is clean and dry."}}},
    "biological":{"material":"not_recyclable","conditionRules":{"clean_dry":{"eligibility":"not_eligible","reason":"Biological waste is not accepted for this recycling pickup."},"contaminated_wet":{"eligibility":"not_eligible","reason":"Biological waste is not accepted for this recycling pickup."},"broken_unsafe":{"eligibility":"not_eligible","reason":"Biological waste is not accepted for this recycling pickup."},"unknown":{"eligibility":"not_eligible","reason":"Biological waste is not accepted for this recycling pickup."}}}
  },"manualSafety":{"batteries":"restricted","bulbs":"restricted","e_waste":"restricted","chemicals":"restricted","sharp_objects":"restricted","other_hazards":"restricted"}}'::jsonb
where name = 'perak_general' and version = 2;

